import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, mix, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-card-1-label';

  const pos = config.scenePosition || { x: 0, y: 1, z: 0.06 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const width = 1.4;
  const height = (320 / 512) * width;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const texNode = texture(map, uv());
  const grainAmount = uniform(0.03);

  const accent = vec4(1.0, 0.165, 0.22, 1.0);
  const ink = vec4(0.086, 0.086, 0.114, 1.0);

  const gradientMix = mix(ink, accent, uv().y);
  const finalColor = mix(texNode, gradientMix, float(0.12));

  material.colorNode = finalColor;
  material.opacityNode = texNode.a;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'features-card-1-label-plane';
  group.add(plane);

  const textMesh = createTextMesh({
    text: 'Features 2',
    fontAtlas: ctx.fontAtlas,
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: '#e8ecf2',
    align: 'center',
    anchor: 'center',
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    while (group.children.length) group.remove(group.children[0]);
  };

  group.userData.handlers = {};

  return group;
}
